CREATE UNIQUE INDEX UX_SessionEvent_OperationKey
    ON SessionEvent (OperationKey)
    WHERE OperationKey IS NOT NULL;

CREATE UNIQUE INDEX UX_ManualAdjustment_SupersedesId
    ON ManualAdjustment (SupersedesId)
    WHERE SupersedesId IS NOT NULL;

ALTER TABLE DailySummaryRevision ADD COLUMN CarryDebtTicks INTEGER NOT NULL DEFAULT 0 CHECK (
    typeof(CarryDebtTicks) = 'integer' AND CarryDebtTicks >= 0);
ALTER TABLE DailySummaryRevision ADD COLUMN DebtPending INTEGER NOT NULL DEFAULT 0 CHECK (
    DebtPending IN (0, 1));

CREATE UNIQUE INDEX UX_ManualAdjustment_SupersedesId
    ON ManualAdjustment (SupersedesId)
    WHERE SupersedesId IS NOT NULL;

CREATE TABLE ActivitySourceSelection (
    Id INTEGER PRIMARY KEY AUTOINCREMENT,
    EffectiveFromUtc TEXT NOT NULL,
    Source TEXT NOT NULL CHECK (Source IN ('built-in', 'activitywatch')),
    CreatedAtUtc TEXT NOT NULL
);
